class Solution:
    def widestLevel(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0
        level = [(root, 0)]
        best = 0
        while level:
            first = level[0][1]
            best = max(best, level[-1][1] - first + 1)
            nxt = []
            for node, slot in level:
                i = slot - first  # re-base so numbers do not grow
                if node.left:
                    nxt.append((node.left, 2 * i))
                if node.right:
                    nxt.append((node.right, 2 * i + 1))
            level = nxt
        return best

