function widestLevel(root: TreeNode | null): number {
  const first: number[] = [];
  let best = 0;
  const dfs = (node: TreeNode | null, depth: number, slot: number): void => {
    if (!node) return;
    if (first.length === depth) first.push(slot); // leftmost of this depth
    const i = slot - first[depth];
    best = Math.max(best, i + 1);
    dfs(node.left, depth + 1, 2 * i);
    dfs(node.right, depth + 1, 2 * i + 1);
  };
  dfs(root, 0, 0);
  return best;
}

